content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

body {
  background-color: #f0f2f5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.calculator-container {
  width: 100%;
  max-width: 360px;
  background-color: #22252d;
  border-radius: 24px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.calculator-display {
  background-color: #2a2d37;
  border-radius: 16px;
  padding: 20px;
  text-align: right;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 90px;
  word-break: break-all;
  word-wrap: break-word;
}

.calculator-display .previous-operand {
  color: #7b7f8e;
  font-size: 14px;
  min-height: 20px;
  margin-bottom: 4px;
}

.calculator-display .current-operand {
  color: #ffffff;
  font-size: 32px;
  font-weight: 500;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.btn {
  background-color: #292d3e;
  color: #ffffff;
  border: none;
  border-radius: 16px;
  font-size: 18px;
  font-weight: 600;
  height: 60px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: flex;
  justify-content: center;
  align-items: center;
  user-select: none;
}

.btn:active {
  transform: scale(0.95);
}

.btn-number {
  background-color: #292d3e;
  color: #ffffff;
}

.btn-number:hover {
  background-color: #353a4d;
}

.btn-operator {
  background-color: #2e3245;
  color: #eb6f6f;
}

.btn-operator:hover {
  background-color: #3b4056;
}

.btn-clear {
  background-color: #3a2e39;
  color: #ff5757;
}

.btn-clear:hover {
  background-color: #4a3a49;
}

.btn-equal {
  background-color: #2692ff;
  color: #ffffff;
}

.btn-equal:hover {
  background-color: #419ffc;
}

.btn-zero {
  grid-column: span 2;
  border-radius: 16px;
}

import { useState } from 'react';
import './App.css';

export default function App() {
  const [currentOperand, setCurrentOperand] = useState<string>('0');
  const [previousOperand, setPreviousOperand] = useState<string>('');
  const [operation, setOperation] = useState<string | null>(null);
  const [resetScreen, setResetScreen] = useState<boolean>(false);

  const handleNumber = (number: string) => {
    if (currentOperand === '0' || resetScreen) {
      setCurrentOperand(number);
      setResetScreen(false);
    } else {
      setCurrentOperand(currentOperand + number);
    }
  };

  const handleDecimal = () => {
    if (resetScreen) {
      setCurrentOperand('0.');
      setResetScreen(false);
      return;
    }
    if (!currentOperand.includes('.')) {
      setCurrentOperand(currentOperand + '.');
    }
  };

  const handleClear = () => {
    setCurrentOperand('0');
    setPreviousOperand('');
    setOperation(null);
    setResetScreen(false);
  };

  const handleOperation = (op: string) => {
    if (operation !== null) {
      evaluate();
    }
    setPreviousOperand(currentOperand);
    setOperation(op);
    setResetScreen(true);
  };

  const evaluate = () => {
    if (operation === null || resetScreen) return;

    const prev = parseFloat(previousOperand);
    const current = parseFloat(currentOperand);

    if (isNaN(prev) || isNaN(current)) return;

    let computation = 0;
    switch (operation) {
      case '+':
        computation = prev + current;
        break;
      case '-':
        computation = prev - current;
        break;
      case '×':
      case '*':
        computation = prev * current;
        break;
      case '÷':
      case '/':
        if (current === 0) {
          alert('ゼロで割ることはできません');
          handleClear();
          return;
        }
        computation = prev / current;
        break;
      default:
        return;
    }

    setCurrentOperand(String(computation));
    setPreviousOperand('');
    setOperation(null);
    setResetScreen(true);
  };

  return (
    <div className="calculator-container">
      <div className="calculator-display">
        <div className="previous-operand">
          {previousOperand} {operation}
        </div>
        <div className="current-operand">{currentOperand}</div>
      </div>
      <div className="keypad">
        <button className="btn btn-clear" onClick={handleClear}>AC</button>
        <button className="btn btn-operator" onClick={() => handleOperation('%')}>%</button>
        <button className="btn btn-operator" onClick={() => handleOperation('÷')}>÷</button>
        <button className="btn btn-operator" onClick={() => handleOperation('×')}>×</button>

        <button className="btn btn-number" onClick={() => handleNumber('7')}>7</button>
        <button className="btn btn-number" onClick={() => handleNumber('8')}>8</button>
        <button className="btn btn-number" onClick={() => handleNumber('9')}>9</button>
        <button className="btn btn-operator" onClick={() => handleOperation('-')}>-</button>

        <button className="btn btn-number" onClick={() => handleNumber('4')}>4</button>
        <button className="btn btn-number" onClick={() => handleNumber('5')}>5</button>
        <button className="btn btn-number" onClick={() => handleNumber('6')}>6</button>
        <button className="btn btn-operator" onClick={() => handleOperation('+')}>+</button>

        <button className="btn btn-number" onClick={() => handleNumber('1')}>1</button>
        <button className="btn btn-number" onClick={() => handleNumber('2')}>2</button>
        <button className="btn btn-number" onClick={() => handleNumber('3')}>3</button>
        <button className="btn btn-equal" onClick={evaluate} style={{ gridRow: 'span 2', height: '100%' }}>=</button>

        <button className="btn btn-number btn-zero" onClick={() => handleNumber('0')}>0</button>
        <button className="btn btn-number" onClick={handleDecimal}>.</button>
      </div>
    </div>
  );
}
